export interface AppEvent {
  name: string;
  payload: unknown;
  timestamp: number;
}

export type EventHandler = (event: AppEvent) => void;

export class EventBus {
  private readonly listeners = new Map<string, EventHandler[]>();

  subscribe(event: string, handler: EventHandler): () => void {
    const handlers = this.listeners.get(event) ?? [];
    handlers.push(handler);
    this.listeners.set(event, handlers);
    return () => {
      const current = this.listeners.get(event);
      if (current === undefined) return;
      const index = current.indexOf(handler);
      if (index >= 0) current.splice(index, 1);
    };
  }

  emit(name: string, payload: unknown = {}): void {
    const event: AppEvent = { name, payload, timestamp: Date.now() };
    for (const handler of this.listeners.get(name) ?? []) {
      handler(event);
    }
  }

  listenerCount(name: string): number {
    return (this.listeners.get(name) ?? []).length;
  }
}

export class IllegalTransitionError extends Error {
  constructor(machine: string, state: string, event: string) {
    super(`State machine "${machine}": no transition from "${state}" on event "${event}"`);
    this.name = 'IllegalTransitionError';
  }
}

export interface TransitionRule {
  from: string;
  to: string;
  on: string;
}

export class StateMachine {
  readonly name: string;
  readonly states: readonly string[];
  readonly transitions: readonly TransitionRule[];
  private currentState: string;

  constructor(name: string, states: string[], initialState: string, transitions: TransitionRule[]) {
    this.name = name;
    this.states = states;
    this.currentState = initialState;
    this.transitions = transitions;
  }

  getState(): string {
    return this.currentState;
  }

  can(event: string): boolean {
    return this.transitions.some(t => t.from === this.currentState && t.on === event);
  }

  transition(event: string): string {
    const rule = this.transitions.find(t => t.from === this.currentState && t.on === event);
    if (rule === undefined) {
      throw new IllegalTransitionError(this.name, this.currentState, event);
    }
    this.currentState = rule.to;
    return this.currentState;
  }
}

