export function verifyArchitecture(): { valid: boolean; errors: string[] } {
  const errors: string[] = [];
  for (const machine of Object.values(machines)) {
    if (!machine.states.includes(machine.getState())) {
      errors.push(`State machine "${machine.name}": initial state is not declared`);
    }
    for (const rule of machine.transitions) {
      if (!machine.states.includes(rule.from)) {
        errors.push(`State machine "${machine.name}": transition from "${rule.from}" is not a declared state`);
      }
      if (!machine.states.includes(rule.to)) {
        errors.push(`State machine "${machine.name}": transition to "${rule.to}" is not a declared state`);
      }
    }
  }
  if (components.length === 0) {
    errors.push('No components declared');
  }
  if (qualityGates.length === 0) {
    errors.push('No quality gates declared');
  }
  return { valid: errors.length === 0, errors };
}
